import{_ as i,o as a,c as t,ak as e}from"./chunks/framework.DJ-92fJv.js";const c=JSON.parse('{"title":"🌐 如何手动解锁网络限制","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"start/network-unlock.md","filePath":"start/network-unlock.md"}'),l={name:"start/network-unlock.md"};function n(h,s,r,d,p,k){return a(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="🌐-如何手动解锁网络限制" tabindex="-1">🌐 如何手动解锁网络限制 <a class="header-anchor" href="#🌐-如何手动解锁网络限制" aria-label="Permalink to “🌐 如何手动解锁网络限制”">​</a></h1><blockquote><p>即使不下载 OsEasy-ToolKit 工具，你也可以手动输入几条命令来解锁噢易学生端的网络限制。本教程手把手教你操作。</p></blockquote><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to “适用场景”">​</a></h2><ul><li>你正在信息课上，电脑被限制了网络</li><li>身边没有 U 盘，无法拷贝工具</li><li>想了解解锁网络的底层原理</li><li>仅需恢复上网功能，不需要解锁其他限制</li></ul><h2 id="第一步-打开命令提示符-cmd" tabindex="-1">第一步：打开命令提示符（CMD） <a class="header-anchor" href="#第一步-打开命令提示符-cmd" aria-label="Permalink to “第一步：打开命令提示符（CMD）”">​</a></h2><p>按 <strong><code>Win + R</code></strong> 键打开&quot;运行&quot;对话框，输入 <code>cmd</code> 后按 <strong>回车</strong> 即可（系统默认以管理员身份运行）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Win + R → 输入 cmd → 回车</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">提示</p><p>机房电脑通常默认登录管理员账户，直接 Win+R 运行 cmd 就是管理员权限，无需额外操作。</p></div><h2 id="第二步-执行解锁命令" tabindex="-1">第二步：执行解锁命令 <a class="header-anchor" href="#第二步-执行解锁命令" aria-label="Permalink to “第二步：执行解锁命令”">​</a></h2><p>依次输入以下 <strong>4 条命令</strong>，每输入一条按一次回车：</p><h3 id="命令-1-停止学生端核心服务" tabindex="-1">命令 1：停止学生端核心服务 <a class="header-anchor" href="#命令-1-停止学生端核心服务" aria-label="Permalink to “命令 1：停止学生端核心服务”">​</a></h3><div class="language-batch"><button title="Copy Code" class="copy"></button><span class="lang">batch</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">sc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> stop MMPC</span></span></code></pre></div><p>停止学生端根服务（MMPC），这是控制所有学生端功能的中心服务。</p><h3 id="命令-2-停止网络限制服务" tabindex="-1">命令 2：停止网络限制服务 <a class="header-anchor" href="#命令-2-停止网络限制服务" aria-label="Permalink to “命令 2：停止网络限制服务”">​</a></h3><div class="language-batch"><button title="Copy Code" class="copy"></button><span class="lang">batch</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">sc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> stop OeNetlimit</span></span></code></pre></div><p>停止专门的网络过滤和限制服务，解除对上网的限制。</p><h3 id="命令-3-终止学生端主进程" tabindex="-1">命令 3：终止学生端主进程 <a class="header-anchor" href="#命令-3-终止学生端主进程" aria-label="Permalink to “命令 3：终止学生端主进程”">​</a></h3><div class="language-batch"><button title="Copy Code" class="copy"></button><span class="lang">batch</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">taskkill</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /f /im Student.exe</span></span></code></pre></div><p>强制终止学生端主程序 <code>Student.exe</code>，防止其继续执行网络管控逻辑。</p><h3 id="命令-4-终止设备控制进程" tabindex="-1">命令 4：终止设备控制进程 <a class="header-anchor" href="#命令-4-终止设备控制进程" aria-label="Permalink to “命令 4：终止设备控制进程”">​</a></h3><div class="language-batch"><button title="Copy Code" class="copy"></button><span class="lang">batch</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">taskkill</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /f /im DeviceControl_x64.exe</span></span></code></pre></div><p>强制终止设备控制进程，解除设备层面的网络限制。</p><h2 id="完整执行示例" tabindex="-1">完整执行示例 <a class="header-anchor" href="#完整执行示例" aria-label="Permalink to “完整执行示例”">​</a></h2><p>以下是完整的执行过程：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\Windows\\System32&gt; sc stop MMPC          ← 停止学生端核心服务</span></span>
<span class="line"><span>C:\\Windows\\System32&gt; sc stop OeNetlimit    ← 停止网络限制服务</span></span>
<span class="line"><span>C:\\Windows\\System32&gt; taskkill /f /im Student.exe         ← 终止学生端</span></span>
<span class="line"><span>C:\\Windows\\System32&gt; taskkill /f /im DeviceControl_x64.exe ← 终止设备控制</span></span></code></pre></div><p>总共就 <strong>4 条命令</strong>，复制粘贴或逐条输入即可，十几秒就能搞定。</p><h2 id="验证解锁成果" tabindex="-1">验证解锁成果 <a class="header-anchor" href="#验证解锁成果" aria-label="Permalink to “验证解锁成果”">​</a></h2><p>解锁后，尝试以下操作验证网络是否恢复：</p><ol><li>打开浏览器，访问任意网站（如 <code>baidu.com</code>）</li><li>如果能正常加载，说明网络已解锁 ✅</li><li>如果仍然受限，尝试 <strong>重启浏览器</strong> 或检查是否还有其他限制</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to “常见问题”">​</a></h2><h3 id="q-解锁后任务栏的网络图标仍然显示-无internet-或黄色感叹号" tabindex="-1">Q：解锁后任务栏的网络图标仍然显示&quot;无Internet&quot;或黄色感叹号？ <a class="header-anchor" href="#q-解锁后任务栏的网络图标仍然显示-无internet-或黄色感叹号" aria-label="Permalink to “Q：解锁后任务栏的网络图标仍然显示&quot;无Internet&quot;或黄色感叹号？”">​</a></h3><p>这是正常现象。学生端网络限制解除后，系统网络状态指示可能需要一段时间才能刷新。<strong>请直接打开浏览器访问任意网站</strong>，你会发现网络实际上已经恢复正常了，不需要理会网络图标的显示状态。</p><h3 id="q-执行-sc-stop-mmpc-提示服务名无效" tabindex="-1">Q：执行 <code>sc stop MMPC</code> 提示服务名无效？ <a class="header-anchor" href="#q-执行-sc-stop-mmpc-提示服务名无效" aria-label="Permalink to “Q：执行 sc stop MMPC 提示服务名无效？”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[SC] OpenService FAILED 1060: 指定的服务未安装。</span></span></code></pre></div><p>这说明这台电脑的噢易版本可能使用了不同的服务名，或者学生端未运行。可以跳过这条命令，尝试直接终止进程。</p><h3 id="q-终止后又自动恢复了怎么办" tabindex="-1">Q：终止后又自动恢复了怎么办？ <a class="header-anchor" href="#q-终止后又自动恢复了怎么办" aria-label="Permalink to “Q：终止后又自动恢复了怎么办？”">​</a></h3><p>噢易学生端有自动保护机制，部分版本会在进程终止后自动重启。如果出现这种情况：</p><ol><li>使用循环终止命令（在 CMD 中运行）：<div class="language-batch"><button title="Copy Code" class="copy"></button><span class="lang">batch</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">loop</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">taskkill</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /f /im Student.exe </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">nul</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">taskkill</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /f /im DeviceControl_x64.exe </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">nul</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">timeout</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /t </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /nobreak </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">nul</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">goto</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> loop</span></span></code></pre></div></li><li>按 <strong><code>Ctrl + C</code></strong> 可以退出循环</li></ol><p>或者直接下载 <a href="/start/download">OsEasy-ToolKit</a> 使用内置的<strong>持续监控模式</strong>。</p><h3 id="q-重启电脑后网络又被限制了" tabindex="-1">Q：重启电脑后网络又被限制了？ <a class="header-anchor" href="#q-重启电脑后网络又被限制了" aria-label="Permalink to “Q：重启电脑后网络又被限制了？”">​</a></h3><p>这是正常的——<code>sc stop</code> 只是停止服务，重启后服务会自动启动。如果需要永久解除，可以执行：</p><div class="language-batch"><button title="Copy Code" class="copy"></button><span class="lang">batch</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">sc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> delete MMPC</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">sc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> delete OeNetlimit</span></span></code></pre></div><div class="danger custom-block"><p class="custom-block-title">警告</p><p>删除服务是<strong>不可逆操作</strong>，只有重新安装噢易软件才能恢复。请谨慎使用。</p></div><h2 id="对比-手动-vs-工具" tabindex="-1">对比：手动 vs 工具 <a class="header-anchor" href="#对比-手动-vs-工具" aria-label="Permalink to “对比：手动 vs 工具”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">方式</th><th style="text-align:left;">优点</th><th style="text-align:left;">缺点</th></tr></thead><tbody><tr><td style="text-align:center;">🛠️ <strong>手动输入</strong></td><td style="text-align:left;">无需下载，即学即用</td><td style="text-align:left;">每次要输 4 条命令，需要记步骤</td></tr><tr><td style="text-align:center;">🚀 <strong>OsEasy-ToolKit</strong></td><td style="text-align:left;">一条命令搞定，带持续监控</td><td style="text-align:left;">需要下载工具</td></tr></tbody></table><h2 id="推荐" tabindex="-1">推荐 <a class="header-anchor" href="#推荐" aria-label="Permalink to “推荐”">​</a></h2><p>对于新手，建议直接使用 <strong>OsEasy-ToolKit 的一键解锁</strong> 功能。理解原理后，以后在任何电脑上都可以手动操作。</p>`,47)])])}const g=i(l,[["render",n]]);export{c as __pageData,g as default};
